// src/utils/parseToGraph.js

export function parseToGraph(code) {
  const lines = code.split("\n").map((l) => l.trim()).filter(Boolean);

  const nodes = lines.map((line, i) => ({
    id: i,
    text: line,
  }));

  const links = lines
    .slice(1)
    .map((_, i) => ({ source: i, target: i + 1 }));

  return { nodes, links };
}

